update public.spell_catalog set name_ru='Морозная сфера', casting_time='Действие', spell_range='300 футов', area='Сфера радиусом 60 футов; при заморозке воды — квадрат 30×30 футов, глубина 6 дюймов', duration='Мгновенно', components=array['В','С','М'], material='миниатюрная хрустальная сфера', concentration=false, ritual=false, check_type='Спасбросок Телосложения; освобождение изо льда — Сила (Атлетика) против Сл спасброска заклинаний', damage='10к6 холодом; половина при успехе', effect_summary='Запускаешь ледяной шар, который взрывается сферой радиусом 60 футов. Если взрыв касается водоёма, вода замерзает на глубину 6 дюймов в квадрате 30 футов на 1 минуту; существа на поверхности оказываются Опутанными. Можно не запускать сферу сразу, а оставить маленький холодный шар в руке и позже бросить его или выстрелить пращой.', upcast='+1к6 урона за каждый уровень ячейки выше 6.', notes='Отложенная сфера взрывается сама через 1 минуту, если не была разбита раньше. Её можно бросить на 40 футов или метнуть пращой на обычную дистанцию пращи.', author_description='Шестьдесят футов холода, возможность заморозить воду и ещё опция сохранить взрыв на потом. Волшебник посмотрел на гранату и решил, что у неё недостаточно функций.', author_comment='Если маг говорит «я пока подержу её в руке», уточни, сколько осталось до минуты.' where slug='freezing-sphere';
update public.spell_catalog set name_ru='Сфера неуязвимости', casting_time='Действие', spell_range='На себя', area='Неподвижная эманация радиусом 10 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='стеклянная бусина', concentration=true, ritual=false, check_type='', damage='', effect_summary='Вокруг тебя появляется неподвижный барьер. Заклинания 5 уровня или ниже, сотворённые снаружи, не могут воздействовать на существ и объекты внутри; область внутри также исключается из площадей таких заклинаний.', upcast='Барьер блокирует заклинания на 1 уровень выше за каждый уровень ячейки выше 6.', notes='Барьер защищает от подходящих заклинаний, сотворённых снаружи. Он неподвижен, даже если ты уходишь из него.', author_description='Десять футов пространства, где чужая магия пятого круга и ниже внезапно становится академической теорией.', author_comment='Очень полезно против магов. Особенно если они забыли подготовить что-нибудь выше пятого уровня.' where slug='globe-of-invulnerability';
update public.spell_catalog set name_ru='Стражи и защиты', casting_time='1 час', spell_range='Касание', area='До 2500 кв. футов пола, высотой до 20 футов', duration='24 часа', components=array['В','С','М'], material='серебряный прут стоимостью 10+ зм', concentration=false, ritual=false, check_type='Отдельные вложенные эффекты используют собственные проверки/спасброски', damage='По выбранным встроенным эффектам', effect_summary='Защищаешь большую область: коридоры заполняются густым туманом и могут путать направление; двери магически запираются, до 10 можно скрыть иллюзиями стен; лестницы покрываются Паутиной, восстанавливающейся за 10 минут; дополнительно размещаешь один набор эффектов — Пляшущие огоньки, Волшебный рот, Зловонное облако, Порыв ветра или Внушение.', upcast='', notes='Можно назначить существ, которых защита игнорирует, и пароль. Рассеивание магии не снимает всё заклинание сразу, но может рассеивать отдельные четыре категории эффектов; когда все четыре сняты, заклинание заканчивается. Ежедневное наложение 365 дней делает защиту постоянной до полного рассеивания.', author_description='Час работы — и здание получает туман, запертые двери, паутину, иллюзии и ещё один сюрприз на выбор. Волшебник наконец превращает паранойю в архитектуру.', author_comment='Если хозяин дома потратил шестой круг на безопасность, стучать лучше очень вежливо.' where slug='guards-and-wards';
update public.spell_catalog set name_ru='Вред', casting_time='Действие', spell_range='60 футов', area='1 видимое существо', duration='Мгновенно', components=array['В','С'], material=null, concentration=false, ritual=false, check_type='Спасбросок Телосложения', damage='14к6 некротического; половина при успехе', effect_summary='При провале цель получает 14к6 некротического урона, а её максимум HP уменьшается на величину реально полученного некротического урона. При успехе получает только половину урона.', upcast='', notes='Максимум HP этим заклинанием нельзя уменьшить ниже 1.', author_description='Четырнадцать к6 и одновременно уменьшение максимума здоровья. Жрец иногда лечит людей, чтобы потом особенно эффектно продемонстрировать обратный процесс.', author_comment='Название короткое. Описание последствий тоже можно сократить до «плохо».' where slug='harm';
update public.spell_catalog set name_ru='Исцеление', casting_time='Действие', spell_range='60 футов', area='1 видимое существо', duration='Мгновенно', components=array['В','С'], material=null, concentration=false, ritual=false, check_type='', damage='Лечение: 70 HP', effect_summary='Цель восстанавливает 70 HP. Также с неё заканчиваются состояния Ослеплённый, Оглохший и Отравленный.', upcast='+10 HP лечения за каждый уровень ячейки выше 6.', notes='Не требует касания и концентрации.', author_description='Семьдесят здоровья одним действием и заодно зрение, слух и яд приводятся в порядок. Иногда жрец действительно полезен настолько, что приходится молчать.', author_comment='Если после семидесяти HP пациент всё ещё жалуется, значит лечение прошло успешно.' where slug='heal';
update public.spell_catalog set name_ru='Пир героев', casting_time='10 минут', spell_range='На себя', area='Пир появляется в свободном кубе 10 футов рядом; до 12 участников', duration='Мгновенно; пир съедается 1 час, преимущества действуют 24 часа', components=array['В','С','М'], material='украшенная драгоценностями чаша стоимостью 1000+ зм, расходуется', concentration=false, ritual=false, check_type='', damage='Каждый участник получает +2к10 к максимуму HP и столько же текущих HP', effect_summary='Создаёшь пир для максимум 12 существ. Его нужно есть 1 час; только после окончания трапезы действуют преимущества на 24 часа: сопротивление урону ядом, иммунитет к состояниям Испуганный и Отравленный, увеличение максимума HP на 2к10 и восстановление того же числа HP.', upcast='', notes='Материальная чаша расходуется. Если пир не закончен, преимущества ещё не действуют.', author_description='Тысяча золотых исчезает, двенадцать человек едят час, а потом сутки чувствуют себя героями. Впервые таверна проиграла магии по цене.', author_comment='Не начинай драку до десерта. Механически это действительно важно.' where slug='heroes-feast';
update public.spell_catalog set name_ru='Мгновенный призыв', casting_time='Действие', spell_range='Касание', area='1 предмет до 10 фунтов и не длиннее 6 футов', duration='До рассеивания', components=array['В','С','М'], material='сапфир стоимостью 1000+ зм', concentration=false, ritual=false, check_type='', damage='', effect_summary='Касаешься сапфира и подходящего предмета, оставляя на предмете невидимую метку и записывая его имя в камне. Позже действием Магии произносишь имя и раздавливаешь сапфир: предмет мгновенно появляется у тебя в руке независимо от расстояния и плана.', upcast='', notes='Для каждого применения нужен отдельный сапфир. Если предмет в этот момент несёт или держит другое существо, он не телепортируется; вместо этого ты узнаёшь, кто держит предмет и где этот носитель находится. Сапфир уничтожается при активации.', author_description='Тысяча золотых за право однажды сказать имя вещи и получить её в руку. Волшебники изобрели чрезвычайно дорогой карман.', author_comment='Если предмет украл плут, заклинание хотя бы сообщит имя подозреваемого. Обычно сюрприза не будет.' where slug='instant-summons';
update public.spell_catalog set name_ru='Неудержимый танец', casting_time='Действие', spell_range='30 футов', area='1 видимое существо', duration='Концентрация, до 1 минуты', components=array['В'], material=null, concentration=true, ritual=false, check_type='Спасбросок Мудрости; при провале цель может действием повторять его каждый ход', damage='', effect_summary='Даже при успешном первом спасброске цель до конца своего следующего хода танцует на месте и обязана потратить всё движение на танец. При провале становится Очарованной: продолжает танцевать, тратит всё движение, получает помеху на атаки и спасброски Ловкости, а атаки по ней совершаются с преимуществом.', upcast='', notes='Очарованная цель может в каждый свой ход потратить Действие, чтобы собраться и повторить спасбросок, заканчивая эффект при успехе.', author_description='Шестой круг магии, чтобы заставить врага танцевать даже после успешного спасброска. Барды называют это искусством. Я — очень агрессивной хореографией.', author_comment='Когда дракон проигрывает бой из-за танца на месте, история становится лучше независимо от исхода.' where slug='irresistible-dance';
update public.spell_catalog set name_ru='Волшебный сосуд', casting_time='1 минута', spell_range='На себя', area='Сосуд и видимые гуманоиды в 100 футах от души', duration='До рассеивания', components=array['В','С','М'], material='драгоценный камень, кристалл или реликварий стоимостью 500+ зм', concentration=false, ritual=false, check_type='Попытка вселения: спасбросок Харизмы цели; смерть тела-носителя: твой спасбросок Харизмы против собственной Сл заклинаний', damage='', effect_summary='Твоё тело впадает в кататонию, а душа входит в материальный сосуд. Из него действием Магии можешь вернуться в тело или попытаться вселиться в видимого гуманоида в 100 футах. При провале его спасброска ты управляешь телом: заменяются твои HP, кости хитов, Сила, Ловкость, Телосложение, Скорость и чувства; остальные игровые параметры сохраняются.', upcast='', notes='Защита от зла и добра и Магический круг блокируют вселение. Цель, успешно спасшаяся, иммунна к новой попытке этого применения на 24 часа. Если тело-носитель умирает, ты возвращаешься в сосуд только при успешном спасброске и если он в 100 футах; иначе умираешь. При уничтожении сосуда/окончании заклинания душа возвращается в исходное живое тело только если оно в 100 футах; иначе ты умираешь. Если в сосуде была чужая душа, для неё действует аналогичное правило. При окончании заклинания сосуд уничтожается.', author_description='Оставляешь тело без сознания, складываешь душу в дорогую банку и начинаешь примерять чужих гуманоидов. Волшебники иногда очень стараются доказать, что некромантия — это не тревожный выбор профессии.', author_comment='Главное правило сосуда: всегда знать, где твоё настоящее тело. Второе главное правило — не путешествовать с плутом.' where slug='magic-jar';
update public.spell_catalog set name_ru='Массовое внушение', casting_time='Действие', spell_range='60 футов', area='До 12 видимых существ, которые слышат и понимают тебя', duration='24 часа', components=array['В','М'], material='язык змеи', concentration=false, ritual=false, check_type='Спасбросок Мудрости каждой цели', damage='', effect_summary='Формулируешь достижимый курс действий не более чем в 25 словах для максимум 12 существ. Он не должен очевидно причинять вред самим целям или их союзникам. При провале цель становится Очарованной и следует внушению до выполнения задачи, окончания длительности или пока ты/союзники не нанесёте ей урон.', upcast='7 уровень: 10 дней; 8: 30 дней; 9: 366 дней.', notes='Не требует концентрации. Для каждой цели эффект заканчивается отдельно, если она завершила предложенную деятельность раньше.', author_description='До двенадцати существ одновременно решают, что твой план звучит разумно. Это уже больше доверия, чем получает большинство настоящих лидеров.', author_comment='Двадцать пять слов. Если не можешь объяснить план короче — возможно, магия здесь ни при чём.' where slug='mass-suggestion';
